--
-- Table structure for table `medicine_trace_codes`
--

DROP TABLE IF EXISTS `medicine_trace_codes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medicine_trace_codes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `medicine_id` int NOT NULL COMMENT '关联药品ID',
  `prescription_id` int DEFAULT NULL COMMENT '关联处方ID',
  `trace_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '药品追溯码',
  `status` enum('pending','scanned_identify','scanned_outbound','scanned_confirm') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'pending' COMMENT '扫描状态',
  `scan1_time` datetime DEFAULT NULL COMMENT '识别药品时间',
  `scan2_time` datetime DEFAULT NULL COMMENT '出库确认时间',
  `scan3_time` datetime DEFAULT NULL COMMENT '最终确认时间',
  `scan1_user_id` int DEFAULT NULL COMMENT '识别操作员',
  `scan2_user_id` int DEFAULT NULL COMMENT '出库操作员',
  `scan3_user_id` int DEFAULT NULL COMMENT '确认操作员',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `trace_code` (`trace_code`) USING BTREE,
  KEY `scan1_user_id` (`scan1_user_id`) USING BTREE,
  KEY `scan2_user_id` (`scan2_user_id`) USING BTREE,
  KEY `scan3_user_id` (`scan3_user_id`) USING BTREE,
  KEY `idx_medicine_id` (`medicine_id`) USING BTREE,
  KEY `idx_prescription_id` (`prescription_id`) USING BTREE,
  CONSTRAINT `medicine_trace_codes_ibfk_1` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `medicine_trace_codes_ibfk_2` FOREIGN KEY (`scan1_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `medicine_trace_codes_ibfk_3` FOREIGN KEY (`scan2_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `medicine_trace_codes_ibfk_4` FOREIGN KEY (`scan3_user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `medicine_trace_codes_ibfk_prescription` FOREIGN KEY (`prescription_id`) REFERENCES `prescriptions` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=7197 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

